<section class="page-hero compact"><div class="container"><span class="eyebrow">Administrator</span><h1>Edit Destination Post</h1></div></section>
<section class="section container"><div class="panel form-panel"><form method="post" action="<?= e(url('admin/post/update')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$post['id'] ?>"><div class="form-grid two"><label>Title<input name="title" value="<?= e($post['title']) ?>" required></label><label>Country<input name="country" value="<?= e($post['country']) ?>" required></label><label>Category<input name="category" value="<?= e($post['category']) ?>" required></label><label>Cost level<select name="cost_level"><?php foreach(['Budget','Moderate','Expensive'] as $opt): ?><option <?= $post['cost_level']===$opt?'selected':'' ?>><?= e($opt) ?></option><?php endforeach; ?></select></label><label class="span-2">Image URL<input type="text" name="image_url" value="<?= e($post['image_url']??'') ?>"></label><label class="span-2">Short history<textarea name="short_history" rows="8" required><?= e($post['short_history']) ?></textarea></label><label class="check-row span-2"><input type="checkbox" name="is_approved" value="1" <?= (int)$post['is_approved']===1?'checked':'' ?>> Published / approved</label></div><div class="form-actions"><a class="btn btn-soft" href="<?= e(url('admin/posts')) ?>">Cancel</a><button class="btn btn-primary" type="submit">Save Post</button></div></form></div></section>
